arguments.query:
query {
      game(slug: "crimson-desert") {
        id name slug status
        collections(first: 20) { nodes { id title slug visibility } pageInfo { total hasMore } }
        content(first: 20, orderBy: "published_at", orderDir: "desc") {
          nodes { id type title slug status publishedAt }
          pageInfo { total hasMore }
        }
      }
      videos(first: 20, orderBy: "published_at", orderDir: "desc") {
        nodes { id title slug status publishedAt game { id name slug } }
        pageInfo { total hasMore }
      }
    }
